from typing import List, Tuple, Union


def validate_interval(interval: Tuple[Union[int, bool], Union[int, bool]]) -> None:
    if not isinstance(interval[0], int) or not isinstance(interval[1], int):
        raise ValueError('Both start and end must be integers')
    if interval[0] > interval[1]:
        raise ValueError('Start of interval cannot be greater than end')


def merge_ranges(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    # Validate each interval before proceeding
    for interval in intervals:
        validate_interval(interval)

    # Sort intervals based on the starting point
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []
    for interval in sorted_intervals:
        if not merged or merged[-1][1] < interval[0]:
            # If list is empty or current interval does not overlap with the previous, simply append it.
            merged.append(interval)
        else:
            # Otherwise, there is an overlap, so we merge the current and previous intervals.
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    return merged

