class Inventory:
    def __init__(self, initial: dict[str, int]):
        self._validate_counts(initial)
        self._counts = initial.copy()

    @staticmethod
    def _validate_counts(counts: dict[str, int]) -> None:
        for count in counts.values():
            if not isinstance(count, int) or count < 0:
                raise ValueError('Counts must be nonnegative integers.')

    def reserve(self, request: dict[str, int]) -> None:
        self._validate_requests(request)
        for sku, quantity in request.items():
            if sku not in self._counts or self._counts[sku] < quantity:
                raise ValueError('Insufficient stock or unknown SKU.')
        for sku, quantity in request.items():
            self._counts[sku] -= quantity

    def snapshot(self) -> dict[str, int]:
        return self._counts.copy()

