from datetime import datetime, timezone


def normalize_timestamp(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError("Input must be a string representing an ISO 8601 datetime with timezone.")

    try:
        # Parse the input string as a datetime object with timezone information
        dt = datetime.fromisoformat(value)
        if dt.tzinfo is None:
            raise ValueError("Naive datetime (without timezone) not allowed.")

        # Convert to UTC and format as YYYY-MM-DDTHH:MM:SSZ
        utc_dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    except ValueError as e:
        raise ValueError(f"Invalid input. {e}") from e

