from typing import List, Tuple

def merge_ranges(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    # Sort intervals based on the starting point
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []
    for interval in sorted_intervals:
        if not merged or merged[-1][1] < interval[0] - 1:
            # If list is empty or current interval does not overlap with the last one in merged list
            merged.append(interval)
        else:
            # There is an overlap, so we merge the current interval with the last one in merged list
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    return merged

