from datetime import datetime, timezone

def normalize_timestamp(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError("Input must be a string in ISO 8601 format with an explicit timezone.")
    try:
        dt = datetime.fromisoformat(value)
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            raise ValueError("Naive date/times are not accepted, provide an explicit timezone.")
        utc_dt = dt.astimezone(timezone.utc).replace(microsecond=0)
        return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    except ValueError as e:
        raise ValueError(f"Invalid input: {e}") from e

